def _existing_transactions_to_one_account(apps, schema_editor):
    """Before accounts existed every statement belonged to the company's main account."""
    BankAccount = apps.get_model("banking", "BankAccount")
    BankTransaction = apps.get_model("banking", "BankTransaction")
    Company = apps.get_model("core", "Company")
    for company in Company.objects.filter(pk__in=BankTransaction.objects.values("company")):
        iban = (company.iban or "").replace(" ", "").upper()
        account = BankAccount.objects.create(company=company, name="Girokonto", iban=iban)
        BankTransaction.objects.filter(company=company, account__isnull=True).update(account=account)


